div.script:
document.getElementById('launch-btn').onclick = async function() {
  try {
    const rawUrl = "https://raw.githubusercontent.com/Mistyitz/EduForgePlatform-/main/index.html";
    const response = await fetch(rawUrl);

    if (!response.ok) throw new Error("Could not load index.html");
    const htmlCode = await response.text();

    const win = window.open('about:blank', '_blank');
    if (win) {
      win.document.open();

      // Script injected into the new page to manage prompt, fullscreen, keyboard locking, and protection rules
      const securityScript = `
        <script>
          window.onload = async function() {
            const confirmLaunch = confirm("EduWorld requires Fullscreen and Focus enforcement. Press OK to proceed or Cancel to exit.");
            if (!confirmLaunch) {
              window.close();
              return;
            }

            // Request Fullscreen
            try {
              if (document.documentElement.requestFullscreen) {
                await document.documentElement.requestFullscreen();
              }
            } catch (e) {
              console.log("Fullscreen request failed or was dismissed.");
            }

            // Lock System Hotkeys (Chrome/Edge supported)
            if (navigator.keyboard && navigator.keyboard.lock) {
              try {
                await navigator.keyboard.lock(['Escape', 'Tab', 'AltLeft', 'AltRight']);
              } catch (e) {
                console.log("Keyboard lock not permitted.");
              }
            }

            // Close tab if full screen is exited
            document.addEventListener('fullscreenchange', () => {
              if (!document.fullscreenElement) {
                alert("Fullscreen mode exited. Closing application.");
                window.close();
              }
            });

            // Close tab if user switches tabs or minimizes
            document.addEventListener('visibilitychange', () => {
              if (document.hidden) {
                window.close();
              }
            });

            // Close tab if window loses focus
            window.addEventListener('blur', () => {
              window.close();
            });
          };
        <\/script>
      `;

      win.document.write(securityScript + htmlCode);
      win.document.close();
    } else {
      alert("Popup blocked! Please allow popups to launch EduWorld.");
    }
  } catch (err) {
    alert("Failed to fetch application code from GitHub.");
  }
};
